<template>
  <div class="nav-shell"><header class="top-bar"><div class="brand"><img :src="brandLogo" class="logo"><span class="title">叶擎慧航</span><span class="role-label">{{ activeRoleName }}</span></div><div class="user-actions"><select v-if="roles.length > 1" v-model="activeRole" @change="switchRole"><option v-for="role in roles" :key="role.code" :value="role.code">{{ role.name }}</option></select><span>{{ username || '用户' }}</span><button @click="logout">退出</button></div></header><nav class="bottom-tab"><button v-for="item in navItems" :key="item.path + item.title" @click="goToPage(item.path)" :class="{active:isCurrentPath(item.path)}"><img :src="item.icon" class="tab-icon"><span>{{ item.title }}</span></button></nav></div>
</template>
<script>
import brandLogo from '@/assets/icons/brand-logo.png'; import homeIcon from '@/assets/icons/home-icon.png'; import fertilizationIcon from '@/assets/icons/fertilization-icon.png'; import deviceIcon from '@/assets/icons/device-icon.png'; import aiIcon from '@/assets/icons/ai-icon.png'; import strategyIcon from '@/assets/icons/strategy-icon.png'; import searchIcon from '@/assets/icons/search-icon.png';
const roleNames={grower:'种植端',plant_protection:'植保端',harvest:'采收端',curing:'烘烤端',quality:'质检端',admin:'管理员端'};
export default {data(){return {brandLogo,username:localStorage.getItem('username')||'',roles:JSON.parse(localStorage.getItem('roles')||'[]'),activeRole:localStorage.getItem('activeRole')||'',allNavItems:[
{path:'/',icon:homeIcon,title:'首页',roles:['grower']},{path:'/workspace-dashboard',icon:homeIcon,title:'工作台',roles:['plant_protection','harvest','curing','quality','admin']},{path:'/recognition',icon:searchIcon,title:'缺素识别',roles:['grower']},{path:'/fertilization',icon:fertilizationIcon,title:'施肥作业',roles:['grower']},{path:'/strategy',icon:strategyIcon,title:'生育期策略',roles:['grower']},{path:'/analysis',icon:strategyIcon,title:'数据分析',roles:['grower']},
{path:'/recognition',icon:searchIcon,title:'病虫识别',roles:['plant_protection']},{path:'/pesticide',icon:fertilizationIcon,title:'农药记录',roles:['plant_protection']},{path:'/analysis/disease',icon:strategyIcon,title:'发生趋势',roles:['plant_protection']},{path:'/device',icon:deviceIcon,title:'植保设备',roles:['plant_protection']},{path:'/harvest',icon:searchIcon,title:'采收批次',roles:['harvest']},{path:'/curing',icon:deviceIcon,title:'烘烤批次',roles:['curing']},{path:'/quality',icon:strategyIcon,title:'质量检验',roles:['quality']},{path:'/admin',icon:deviceIcon,title:'用户与角色',roles:['admin']},{path:'/ai',icon:aiIcon,title:'AI 助手',roles:['grower','plant_protection','harvest','curing','quality','admin']}]};},computed:{navItems(){const active=this.activeRole||this.roles[0]?.code;return this.allNavItems.filter(item=>item.roles.includes(active)).slice(0,5);},activeRoleName(){return roleNames[this.activeRole]||'工作台';}},mounted(){this.onRoleChange=e=>{this.activeRole=e.detail;};window.addEventListener('role-change',this.onRoleChange);},beforeUnmount(){window.removeEventListener('role-change',this.onRoleChange);},methods:{switchRole(){localStorage.setItem('activeRole',this.activeRole);window.dispatchEvent(new CustomEvent('role-change',{detail:this.activeRole}));this.$router.push(['grower','plant_protection'].includes(this.activeRole)?'/':'/workspace-dashboard');},goToPage(path){if(this.$route.path!==path)this.$router.push(path);},isCurrentPath(path){return path==='/'?this.$route.path==='/':path==='/fertilization'?(this.$route.path==='/fertilization'||this.$route.path==='/pesticide'):this.$route.path===path;},logout(){['token','userId','username','roles','activeRole'].forEach(k=>localStorage.removeItem(k));this.$router.push('/login');}}};
</script>
