@media(min-width:1024px){.bottom-tab{top:var(--header-h);bottom:0;right:auto;width:196px;min-height:0;padding:16px 8px;display:flex;flex-direction:column;gap:4px;border-top:0;border-right:1px solid var(--color-border)}.bottom-tab button{width:100%;min-height:42px;flex-direction:row;justify-content:flex-start;gap:12px;padding:0 12px;font-size:13px}}
